import assert from 'node:assert/strict';import {pathToFileURL} from 'node:url';
let input='';for await(const c of process.stdin) input+=c;const cfg=JSON.parse(input);
const {chromium}=await import(pathToFileURL(cfg.module+'/index.mjs').href);const browser=await chromium.launch({headless:true,...(cfg.executable?{executablePath:cfg.executable}:{})});
try {const page=await browser.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));const cdp=await page.context().newCDPSession(page);
const tags={dial:'LIGHTNING-CLICK-TO-DIAL',empty:'LIGHTNING-EMPTY-STATE',button:'LIGHTNING-RICH-TEXT-TOOLBAR-BUTTON',group:'LIGHTNING-RICH-TEXT-TOOLBAR-BUTTON-GROUP'};
function compact(root){let out=[];function walk(n){if(['svg','LIGHTNING-PRIMITIVE-ICON','LIGHTNING-POPUP'].includes(n.nodeName) || (n.attributes||[]).includes('hidden'))return;let attrs={};for(let i=0;i<(n.attributes||[]).length;i+=2){let k=n.attributes[i],v=n.attributes[i+1];if(['role','aria-disabled','aria-label','aria-pressed','disabled','title','name','slot','part'].includes(k))attrs[k]=v;}if(['SPAN','BUTTON','DIV','H3','SLOT','P'].includes(n.nodeName))out.push({tag:n.nodeName.toLowerCase(),...attrs});if(n.nodeName==='#text'&&n.nodeValue.trim())out.push({text:n.nodeValue.trim()});for(const ch of [...(n.shadowRoots||[]),...(n.children||[])])walk(ch);}walk(root);return out;}
for(const [id,tag] of Object.entries(tags)){await page.goto(cfg.url+'/?'+id);await page.waitForFunction(()=>window.__ready===true,{timeout:15000});const root=(await cdp.send('DOM.getDocument',{depth:-1,pierce:true})).root;let hits=[];function visit(n){if(n.nodeName===tag){hits.push(compact(n));return;}for(const k of [...(n.shadowRoots||[]),...(n.children||[])])visit(k);}visit(root);for(const row of cfg.rows.filter(r=>r[0]===id))assert.deepEqual(hits,JSON.parse(row[2]),`${id} API ${row[1]}`);}
await page.goto(cfg.url+'/?extra');await page.waitForFunction(()=>window.__ready===true);
const empty=page.locator('lightning-empty-state'), button=page.locator('lightning-rich-text-toolbar-button');
for(const [id,api,expected] of cfg.extraRows){const native=JSON.parse(expected);if(id==='empty'){
 const observed=await empty.evaluateAll(els=>els.map(e=>Object.fromEntries(['title','headingLevel','illustrationName','alternativeText','size'].map(k=>[k,e[k]===undefined?'undefined':e[k]]))));assert.deepEqual(observed,native.initial,`empty public properties ${api}`);
 assert.equal(await empty.nth(0).locator('h3').getAttribute('aria-level'),'2');assert.equal(await empty.nth(1).locator('h3').getAttribute('aria-level'),null);assert.equal(await empty.nth(0).locator('svg').count(),1);assert.equal(await empty.nth(1).locator('svg').count(),0);
}else{
 const initial=await button.evaluate(e=>({show:typeof e.showPopup,close:typeof e.closePopup,selected:e.selected}));assert.deepEqual(initial,native.initial,`toolbar initial ${api}`);
 const control=button.locator('button');await control.click();assert.deepEqual({pressed:await control.getAttribute('aria-pressed'),selected:await button.evaluate(e=>e.selected)},native.afterFirst);
 await button.evaluate(e=>e.showPopup());assert.equal(await page.getByText('Popup content',{exact:true}).isVisible(),true);await button.evaluate(e=>e.closePopup());await page.getByText('Popup content',{exact:true}).waitFor({state:'hidden',timeout:3000});
}}
for(const [,api,raw] of cfg.clickoutRows){const native=JSON.parse(raw);await button.evaluate(e=>e.showPopup());await page.locator('#outside').click();await page.waitForTimeout(100);assert.equal((await page.evaluate(()=>window.__popupEvents.length)),0,`unexpected popupclickout ${api}`);assert.equal(await page.getByText('Popup content',{exact:true}).count(),native.first.visible);await page.evaluate(()=>window.__preventClickout=true);await page.locator('#outside').click();await page.keyboard.press('Escape');await page.waitForTimeout(100);assert.equal((await page.evaluate(()=>window.__popupEvents.length)),0);assert.equal(await page.getByText('Popup content',{exact:true}).count(),native.escape.visible);await button.evaluate(e=>e.closePopup());await page.getByText('Popup content',{exact:true}).waitFor({state:'hidden',timeout:3000});}
assert.deepEqual(errors,[]);
}finally{await browser.close()}
